const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const query = $json.query ?? {};
const rawFrom = body.from || body.sender || body.phone || body?.message?.from || '';
const text = body.text || body.message?.text || body.body?.text || body?.message?.body?.text || body?.message?.text?.body || '';
const messageId = body.message_id || body.message?.id || body.id || '';
const timestamp = body.timestamp || body.message?.timestamp || new Date().toISOString();
const digits = String(rawFrom || '').replace(/\D/g, '');
const normalized = digits ? `+${digits}` : '';
const owner = $env.OWNER_WHATSAPP || '';
const secretHeader = headers['x-origin-secret'] || headers['X-ORIGIN-SECRET'];
const secretQuery = query.secret || body.secret || '';
const providedSecret = secretHeader || secretQuery || '';
