const today = new Date();
const parseDate = (value) => {
  if (!value) return null;
  if (typeof value === 'number') {
    const utc = Math.round((value - 25569) * 86400 * 1000);
    return new Date(utc);
  }
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
};
const normalizePhone = (value) => `+${String(value || '').replace(/\D/g, '')}`;
const result = [];
for (const item of $input.all()) {
  const c = item.json;
  if (String(c.consentimiento_mensajes || '').toUpperCase() !== 'SI') continue;
  if (String(c.estado || '').toUpperCase() === 'SUSPENDIDO') continue;
  const venc = parseDate(c.proximo_vencimiento);
  if (!venc) continue;
  const diff = Math.floor((new Date(venc.toDateString()) - new Date(today.toDateString())) / 86400000);
  let tipo = null;
  if (diff === 7) tipo = 'RECORDATORIO_7D';
  else if (diff === 2) tipo = 'RECORDATORIO_2D';
  else if (diff === 0) tipo = 'VENCE_HOY';
  else if (diff === -3) tipo = 'SEGUIMIENTO_3D';
  else if (diff === -7) tipo = 'SEGUIMIENTO_7D';
  else if (diff === -14) tipo = 'MOROSO_14D';
  if (!tipo) continue;
  const messageKey = `${c.cliente_id || ''}_${tipo}_${c.proximo_vencimiento || ''}`;
  result.push({ json: {
    cliente_id: c.cliente_id || '',
    nombre: c.nombre || '',
    whatsapp: normalizePhone(c.whatsapp || ''),
    link_pago: c.link_pago || '',
    proximo_vencimiento: c.proximo_vencimiento || '',
    tipo_mensaje: tipo,
    message_key: messageKey
  } });
}
return result;

