const today = new Date();
const parseDate = (value) => {
  if (!value) return null;
  if (typeof value === 'number') {
    const utc = Math.round((value - 25569) * 86400 * 1000);
    return new Date(utc);
  }
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
};
let totalActivos = 0;
let porVencer = 0;
let vencenHoy = 0;
let vencidos1_7 = 0;
let morosos8Mas = 0;
let montoEsperado = 0;
for (const item of $input.all()) {
  const c = item.json;
  if (String(c.estado || '').toUpperCase() !== 'ACTIVO') continue;
  totalActivos += 1;
  const monto = Number(c.monto_mensual || 0);
  montoEsperado += Number.isNaN(monto) ? 0 : monto;
  const venc = parseDate(c.proximo_vencimiento);
  if (!venc) continue;
  const diff = Math.floor((new Date(venc.toDateString()) - new Date(today.toDateString())) / 86400000);
  if (diff >= 0 && diff <= 2) porVencer += 1;
  if (diff === 0) vencenHoy += 1;
  if (diff < 0 && diff >= -7) vencidos1_7 += 1;
  if (diff <= -8) morosos8Mas += 1;
}
return [{ json: { totalActivos, porVencer, vencenHoy, vencidos1_7, morosos8Mas, montoEsperado } }];

